{
  "status": "SUPPORTED",
  "task_summary": "Arrange two refreshment settings on side tables and move a remote to the central table.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Hold beverage and food for one person",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup", "plate", "glass"],
        "required_properties": ["holds liquid", "holds solid food"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Operate the television",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["remote control"],
        "required_properties": ["wireless operation"]
      },
      {
        "id": "side_table",
        "entity_kind": "REGION",
        "function": "Surface adjacent to seating for personal items",
        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": ["end table", "side table"],
        "required_properties": ["flat surface", "near chair"]
      },
      {
        "id": "central_table",
        "entity_kind": "REGION",
        "function": "Shared surface accessible to both people",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["coffee table"],
        "required_properties": ["central location", "flat surface"]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_location",
        "relation": "is_near",
        "participant_roles": ["refreshment_setting", "side_table"],
        "required": true
      },
      {
        "id": "control_location",
        "relation": "is_on",
        "participant_roles": ["entertainment_control", "central_table"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "place_refreshments",
        "operation": "place",
        "participant_roles": ["refreshment_setting", "side_table"],
        "operation_count": 2
      },
      {
        "id": "place_remote",
        "operation": "place",
        "participant_roles": ["entertainment_control", "central_table"],
        "operation_count": 1
      }
    ]
  },
